program.source:
Subroutine Suspendable Double(number As Integer) As Integer
  Return number * 2;
EndSubroutine

Subroutine Suspendable Triple(number As Integer) As Integer
  Return number * 3;
EndSubroutine

Algorithm DoubleAndTriple
  Define number As Integer;
  Read number;
  Tasks
    Define twice As Task<Integer> <- Spawn Double(number);
    Define thrice As Task<Integer> <- Spawn Triple(number);
    Define tripleShare As Integer <- 0;
    Write Await twice + tripleShare;
    tripleShare <- Await thrice;
  EndTasks
EndAlgorithm

